  });

  const [isMuted, setIsMuted] = useState(true);
  const [isVideoOff, setIsVideoOff] = useState(true);
  const [recentRooms, setRecentRooms] = useState([]);
  const [theme, setTheme] = useState(() => getThemePreference());

  useLayoutEffect(() => {
