    if (!themeInitializedRef.current) {
      themeInitializedRef.current = true;
      return undefined;
    }

    root.classList.add('theme-transition');
    const timeoutId = window.setTimeout(() => root.classList.remove('theme-transition'), 220);
    return () => {
      window.clearTimeout(timeoutId);
      root.classList.remove('theme-transition');
    };
  }, [theme]);

  const handleThemeChange = useCallback((nextTheme) => {
    setTheme(setThemePreference(nextTheme));
  }, []);

  const effectiveRuntimeConfig = useMemo(() => (
    runtimeConfig
      ? {
        ...runtimeConfig,
        features: {
          ...runtimeConfig.features,
          nativeStt: sttStatus ? sttStatus.nativeReady === true : runtimeConfig.features.nativeStt
        },
        stt: sttStatus || runtimeConfig.stt
      }
      : runtimeConfig
  ), [runtimeConfig, sttStatus]);

  const {
    localStream,
